import numpy as np
from Bio.PDB import PDBParser
import heapq
from test_margin import build_grid

parser = PDBParser(QUIET=True)
s = parser.get_structure('m1', '/task/input/models/model_01.pdb')
min_int, shape, is_open, x_range, y_range, z_range = build_grid(8)

P = s[0]['A'][1]['CA'].coord
Q = s[0]['C'][20]['CA'].coord

neighbors = []
for dx in [-1, 0, 1]:
    for dy in [-1, 0, 1]:
        for dz in [-1, 0, 1]:
            if dx == 0 and dy == 0 and dz == 0:
                continue
            w = float(np.sqrt(dx*dx + dy*dy + dz*dz))
            neighbors.append((dx, dy, dz, w))

p_min = np.maximum(0, np.floor(P - 7.0).astype(int) - min_int)
p_max = np.minimum(np.array(shape) - 1, np.ceil(P + 7.0).astype(int) - min_int)

pq = []
dist = np.full(shape, np.inf, dtype=np.float32)
for ix in range(p_min[0], p_max[0] + 1):
    for iy in range(p_min[1], p_max[1] + 1):
        for iz in range(p_min[2], p_max[2] + 1):
            if is_open[ix, iy, iz]:
                pt = np.array([x_range[ix], y_range[iy], z_range[iz]])
                d = float(np.linalg.norm(pt - P))
                if d <= 7.0:
                    dist[ix, iy, iz] = d
                    heapq.heappush(pq, (d, ix, iy, iz))

while pq:
    d, cx, cy, cz = heapq.heappop(pq)
    if d > dist[cx, cy, cz]:
        continue
    if d > 34.0:
        break
    for dx, dy, dz, w in neighbors:
        nx, ny, nz = cx + dx, cy + dy, cz + dz
        if 0 <= nx < shape[0] and 0 <= ny < shape[1] and 0 <= nz < shape[2]:
            if is_open[nx, ny, nz]:
                nd = d + w
                if nd < dist[nx, ny, nz] and nd <= 34.0:
                    dist[nx, ny, nz] = nd
                    heapq.heappush(pq, (nd, nx, ny, nz))

# Now find min over S_Q
q_min = np.maximum(0, np.floor(Q - 7.0).astype(int) - min_int)
q_max = np.minimum(np.array(shape) - 1, np.ceil(Q + 7.0).astype(int) - min_int)
best_dijkstra = np.inf
for ix in range(q_min[0], q_max[0] + 1):
    for iy in range(q_min[1], q_max[1] + 1):
        for iz in range(q_min[2], q_max[2] + 1):
            if is_open[ix, iy, iz]:
                pt = np.array([x_range[ix], y_range[iy], z_range[iz]])
                dQ = float(np.linalg.norm(pt - Q))
                if dQ <= 7.0:
                    best_dijkstra = min(best_dijkstra, dist[ix, iy, iz] + dQ)

print(f'Dijkstra result: {best_dijkstra:.4f}')
