import numpy as np
import time
import heapq
import pandas as pd
from Bio.PDB import PDBParser
from Bio.SeqUtils import seq1

def xlmbql_pos_to_model(p):
    if 84 <= p <= 175:
        return p - 83
    elif 189 <= p <= 381:
        return p - 189 + 93
    return None

def xlcq5e_pos_to_model(p):
    if 87 <= p <= 235:
        return p - 86
    elif 243 <= p <= 346:
        return p - 243 + 150
    return None

neighbors = []
for dx in [-1, 0, 1]:
    for dy in [-1, 0, 1]:
        for dz in [-1, 0, 1]:
            if dx == 0 and dy == 0 and dz == 0:
                continue
            w = float(np.sqrt(dx*dx + dy*dy + dz*dz))
            neighbors.append((dx, dy, dz, w))

def build_grid(coords, margin=8):
    min_int = np.floor(coords.min(axis=0) - margin).astype(int)
    max_int = np.ceil(coords.max(axis=0) + margin).astype(int)
    x_range = np.arange(min_int[0], max_int[0] + 1)
    y_range = np.arange(min_int[1], max_int[1] + 1)
    z_range = np.arange(min_int[2], max_int[2] + 1)
    shape = (len(x_range), len(y_range), len(z_range))
    is_open = np.ones(shape, dtype=bool)

    for c in coords:
        ix_min = max(0, int(np.ceil(c[0] - 3.0 + 1e-9)) - min_int[0])
        ix_max = min(shape[0] - 1, int(np.floor(c[0] + 3.0 - 1e-9)) - min_int[0])
        iy_min = max(0, int(np.ceil(c[1] - 3.0 + 1e-9)) - min_int[1])
        iy_max = min(shape[1] - 1, int(np.floor(c[1] + 3.0 - 1e-9)) - min_int[1])
        iz_min = max(0, int(np.ceil(c[2] - 3.0 + 1e-9)) - min_int[2])
        iz_max = min(shape[2] - 1, int(np.floor(c[2] + 3.0 - 1e-9)) - min_int[2])
        if ix_min > ix_max or iy_min > iy_max or iz_min > iz_max:
            continue
        xs = x_range[ix_min:ix_max+1][:, None, None]
        ys = y_range[iy_min:iy_max+1][None, :, None]
        zs = z_range[iz_min:iz_max+1][None, None, :]
        d2 = (xs - c[0])**2 + (ys - c[1])**2 + (zs - c[2])**2
        is_open[ix_min:ix_max+1, iy_min:iy_max+1, iz_min:iz_max+1] &= ~(d2 < 9.0)
    return min_int, shape, is_open, x_range, y_range, z_range

def astar_distance(P, Q, min_int, shape, is_open, x_range, y_range, z_range, max_dist=34.0):
    euc = np.linalg.norm(P - Q)
    if euc > max_dist:
        return np.inf

    p_min = np.maximum(0, np.floor(P - 7.0).astype(int) - min_int)
    p_max = np.minimum(np.array(shape) - 1, np.ceil(P + 7.0).astype(int) - min_int)

    q_min = np.maximum(0, np.floor(Q - 7.0).astype(int) - min_int)
    q_max = np.minimum(np.array(shape) - 1, np.ceil(Q + 7.0).astype(int) - min_int)

    has_open_q = False
    for ix in range(q_min[0], q_max[0] + 1):
        for iy in range(q_min[1], q_max[1] + 1):
            for iz in range(q_min[2], q_max[2] + 1):
                if is_open[ix, iy, iz]:
                    pt = np.array([x_range[ix], y_range[iy], z_range[iz]])
                    if np.linalg.norm(pt - Q) <= 7.0:
                        has_open_q = True
                        break
            if has_open_q: break
        if has_open_q: break

    if not has_open_q:
        return np.inf

    pq = []
    g_score = {}
    best_dist = np.inf

    for ix in range(p_min[0], p_max[0] + 1):
        for iy in range(p_min[1], p_max[1] + 1):
            for iz in range(p_min[2], p_max[2] + 1):
                if is_open[ix, iy, iz]:
                    pt = np.array([x_range[ix], y_range[iy], z_range[iz]])
                    dP = float(np.linalg.norm(pt - P))
                    if dP <= 7.0:
                        dQ = float(np.linalg.norm(pt - Q))
                        if dQ <= 7.0:
                            best_dist = min(best_dist, dP + dQ)
                        h = dQ
                        f = dP + h
                        if f <= max_dist:
                            g_score[(ix, iy, iz)] = dP
                            heapq.heappush(pq, (f, dP, ix, iy, iz))

    while pq:
        f, g, cx, cy, cz = heapq.heappop(pq)
        if g > g_score.get((cx, cy, cz), np.inf):
            continue
        if f >= best_dist or f > max_dist:
            break

        for dx, dy, dz, w in neighbors:
            nx, ny, nz = cx + dx, cy + dy, cz + dz
            if 0 <= nx < shape[0] and 0 <= ny < shape[1] and 0 <= nz < shape[2]:
                if is_open[nx, ny, nz]:
                    ng = g + w
                    pos = (nx, ny, nz)
                    if ng < g_score.get(pos, np.inf):
                        pt = np.array([x_range[nx], y_range[ny], z_range[nz]])
                        dQ = float(np.linalg.norm(pt - Q))
                        if dQ <= 7.0:
                            best_dist = min(best_dist, ng + dQ)
                        h = dQ
                        nf = ng + h
                        if nf < best_dist and nf <= max_dist:
                            g_score[pos] = ng
                            heapq.heappush(pq, (nf, ng, nx, ny, nz))
    return best_dist

def evaluate_model(pdb_path, xl_df):
    parser = PDBParser(QUIET=True)
    m_id = pdb_path.split('/')[-1].replace('.pdb', '')
    s = parser.get_structure(m_id, pdb_path)

    chains_map = {'XLMBQL': [], 'XLCQ5E': []}
    for c in s.get_chains():
        res = [r for r in c.get_residues() if r.id[0] == ' ']
        if len(res) == 285:
            chains_map['XLMBQL'].append(c.id)
        elif len(res) == 253:
            chains_map['XLCQ5E'].append(c.id)
        else:
            raise ValueError(f'Unexpected chain length {len(res)} in {pdb_path} chain {c.id}')

    coords = np.array([atom.coord for atom in s.get_atoms() if atom.element != 'H'])
    min_int, shape, is_open, x_range, y_range, z_range = build_grid(coords, margin=8)

    results = {}
    inter_sat = 0
    inter_tot = 0
    intra_sat = 0
    intra_tot = 0

    for idx, row in xl_df.iterrows():
        xl_id = row['xl_id']
        pa = row['protein_a']
        pb = row['protein_b']
        pos_a = row['position_a']
        pos_b = row['position_b']
        is_inter = (pa != pb)

        m_a = xlmbql_pos_to_model(pos_a) if pa == 'XLMBQL' else xlcq5e_pos_to_model(pos_a)
        m_b = xlmbql_pos_to_model(pos_b) if pb == 'XLMBQL' else xlcq5e_pos_to_model(pos_b)

        if m_a is None or m_b is None:
            results[xl_id] = 'not_evaluable'
            continue

        if is_inter:
            inter_tot += 1
        else:
            intra_tot += 1

        chains_a = chains_map[pa]
        chains_b = chains_map[pb]

        assignments = []
        if is_inter:
            for ca in chains_a:
                for cb in chains_b:
                    assignments.append((ca, cb))
        else:
            if pos_a == pos_b:
                assignments.append((chains_a[0], chains_a[1]))
            else:
                assignments.append((chains_a[0], chains_a[0]))
                assignments.append((chains_a[1], chains_a[1]))
                assignments.append((chains_a[0], chains_a[1]))
                assignments.append((chains_a[1], chains_a[0]))

        asgn_with_dist = []
        for ca, cb in assignments:
            coord_a = s[0][ca][m_a]['CA'].coord
            coord_b = s[0][cb][m_b]['CA'].coord
            euc = np.linalg.norm(coord_a - coord_b)
            asgn_with_dist.append((euc, ca, cb, coord_a, coord_b))
        asgn_with_dist.sort(key=lambda x: x[0])

        satisfied = False
        for euc, ca, cb, coord_a, coord_b in asgn_with_dist:
            if euc > 34.0:
                continue
            surf_dist = astar_distance(coord_a, coord_b, min_int, shape, is_open, x_range, y_range, z_range, max_dist=34.0)
            if surf_dist <= 34.0:
                satisfied = True
                break

        if satisfied:
            results[xl_id] = 'satisfied'
            if is_inter:
                inter_sat += 1
            else:
                intra_sat += 1
        else:
            results[xl_id] = 'violated'

    return results, inter_sat, inter_tot, intra_sat, intra_tot

if __name__ == '__main__':
    xl_df = pd.read_csv('/task/input/crosslinks.csv')
    t0 = time.time()
    res, inter_sat, inter_tot, intra_sat, intra_tot = evaluate_model('/task/input/models/model_01.pdb', xl_df)
    t1 = time.time()
    print(f'Model 01 evaluated in {t1 - t0:.2f} s')
    print(f'Inter: {inter_sat} / {inter_tot}, Intra: {intra_sat} / {intra_tot}, Total: {inter_sat + intra_sat} / {inter_tot + intra_tot}')
